  1→import { useRef, useState } from 'react';
  2→import { useTranslation } from '../hooks/useTranslation';
  3→import type { TableInfo } from '../types';
  4→import { SkillsPanel } from './SkillsPanel';
  5→import { MemoriesPanel } from './MemoriesPanel';
  6→import { CreateSkillDialog } from './CreateSkillDialog';
  7→import { ConversationHistory } from './ConversationHistory';
  8→import './Sidebar.css';
  9→
 10→interface SidebarProps {
 11→  tables: TableInfo[];
 12→  onTableClick: (tableName: string) => void;
 13→  onTableDelete: (tableName: string) => void;
 14→  onUpload: (files: File[]) => void;
 15→  onDeleteAll: () => void;
 16→  collapsed: boolean;
 17→  onToggle: () => void;
 18→  onUseSkill?: (skillName: string) => void;
 19→  activeConversationId: string | null;
 20→  onConversationSelect: (id: string) => void;
 21→  onConversationNew: () => void;
 22→  onConversationDelete: (id: string) => void;
 23→  onConversationRename: (id: string, title: string) => void;
 24→  conversationRefreshTrigger: number;
 25→  sessionId: string;
 26→  streamingConversationIds: Set<string>;
 27→}
 28→
 29→export function Sidebar({ tables, onTableClick, onTableDelete, onUpload, onDeleteAll, collapsed, onToggle, onUseSkill, activeConversationId, onConversationSelect, onConversationNew, onConversationDelete, onConversationRename, conversationRefreshTrigger, sessionId, streamingConversationIds }: SidebarProps) {
 30→  const { t } = useTranslation();
 31→  const [expanded, setExpanded] = useState<Record<string, boolean>>({});
 32→  const fileInputRef = useRef<HTMLInputElement>(null);
 33→  const [activeTab, setActiveTab] = useState<'tables' | 'skills' | 'memories'>('tables');
 34→  const [showCreateDialog, setShowCreateDialog] = useState(false);
 35→  const [skillsRefreshKey, setSkillsRefreshKey] = useState(0);
 36→  const [memoriesRefreshKey, setMemoriesRefreshKey] = useState(0);
 37→
 38→  const toggle = (name: string) => {
 39→    setExpanded((prev) => ({ ...prev, [name]: !prev[name] }));
 40→  };
 41→
 42→  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
 43→    const files = e.target.files;
 44→    if (files && files.length > 0) {
 45→      onUpload(Array.from(files));
 46→    }
 47→    if (fileInputRef.current) {
 48→      fileInputRef.current.value = '';
 49→    }
 50→  };
 51→
 52→  return (
 53→    <>
 54→    <div className={`sidebar ${collapsed ? 'sidebar--collapsed' : ''}`}>
 55→      <div className="sidebar__top">
 56→        <div className="sidebar__header">
 57→          <div className="sidebar__tabs">
 58→            <button
 59→              className={`sidebar__tab ${activeTab === 'tables' ? 'sidebar__tab--active' : ''}`}
 60→              onClick={() => setActiveTab('tables')}
 61→            >
 62→              {t('tablesTab')}
 63→            </button>
 64→            <button
 65→              className={`sidebar__tab ${activeTab === 'skills' ? 'sidebar__tab--active' : ''}`}
 66→              onClick={() => setActiveTab('skills')}
 67→            >
 68→              {t('skillsTab')}
 69→            </button>
 70→            <button
 71→              className={`sidebar__tab ${activeTab === 'memories' ? 'sidebar__tab--active' : ''}`}
 72→              onClick={() => { setActiveTab('memories'); setMemoriesRefreshKey((k) => k + 1); }}
 73→            >
 74→              {t('memoriesTab')}
 75→            </button>
 76→          </div>
 77→          <button
 78→            className="sidebar__collapse-toggle"
 79→            onClick={onToggle}
 80→            aria-label={collapsed ? t('expandSidebar') : t('collapseSidebar')}
 81→          >
 82→            <span className="sidebar__hamburger" />
 83→          </button>
 84→        </div>
 85→      </div>
 86→      <div className="sidebar__content">
 87→        {activeTab === 'tables' ? (
 88→          <>
 89→            <div className="sidebar__actions">
 90→              <input
 91→                ref={fileInputRef}
 92→                type="file"
 93→                multiple
 94→                accept=".csv,.json,.parquet,.xlsx"
 95→                onChange={handleFileChange}
 96→                hidden
 97→              />
 98→              <button
 99→                className="sidebar__action-btn"
100→                onClick={() => fileInputRef.current?.click()}
101→                title={t('uploadFiles')}
102→                aria-label={t('uploadFiles')}
103→              >
104→                <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
105→                  <path d="M21 15v4a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2v-4" />
106→                  <polyline points="17 8 12 3 7 8" />
107→                  <line x1="12" y1="3" x2="12" y2="15" />
108→                </svg>
109→              </button>
110→              <button
111→                className="sidebar__action-btn sidebar__action-btn--danger"
112→                onClick={onDeleteAll}
113→                title={t('deleteAllTables')}
114→                aria-label={t('deleteAllTables')}
115→                disabled={tables.length === 0}
116→              >
117→                <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
118→                  <polyline points="3 6 5 6 21 6" />
119→                  <path d="M19 6v14a2 2 0 0 1-2 2H7a2 2 0 0 1-2-2V6m3 0V4a2 2 0 0 1 2-2h4a2 2 0 0 1 2 2v2" />
120→                </svg>
121→              </button>
122→            </div>
123→            {tables.length === 0 && (
124→              <p className="sidebar__empty">{t('noTables')}</p>
125→            )}
126→            <ul className="sidebar__list">
127→              {tables.map((table) => (
128→                <li key={table.name} className="sidebar__item">
129→                  <div className="sidebar__table-header">
130→                    <button
131→                      className="sidebar__toggle"
132→                      onClick={() => toggle(table.name)}
133→                    >
134→                      {expanded[table.name] ? '\u25BC' : '\u25B6'}
135→                    </button>
136→                    <button
137→                      className="sidebar__table-name"
138→                      onClick={() => { onTableClick(table.name); toggle(table.name); }}
139→                      title={table.name}
140→                    >
141→                      {table.name}
142→                    </button>
143→                    <span className="sidebar__row-count">
144→                      {t('rowCount', { count: table.rowCount })}
145→                    </span>
146→                    <button
147→                      className="sidebar__delete"
148→                      onClick={(e) => {
149→                        e.stopPropagation();
150→                        onTableDelete(table.name);
151→                      }}
152→                      title={t('deleteTable', { name: table.name })}
153→                      aria-label={t('deleteTable', { name: table.name })}
154→                    >
155→                      <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><polyline points="3 6 5 6 21 6"/><path d="M19 6v14a2 2 0 0 1-2 2H7a2 2 0 0 1-2-2V6m3 0V4a2 2 0 0 1 2-2h4a2 2 0 0 1 2 2v2"/></svg>
156→                    </button>
157→                  </div>
158→                  {expanded[table.name] && (
159→                    <ul className="sidebar__columns">
160→                      {table.columns.map((col) => (
161→                        <li key={col.name} className="sidebar__column">
162→                          <span className="sidebar__col-name">{col.name}</span>
163→                          <span className="sidebar__col-type">{col.type}</span>
164→                        </li>
165→                      ))}
166→                    </ul>
167→                  )}
168→                </li>
169→              ))}
170→            </ul>
171→          </>
172→        ) : activeTab === 'skills' ? (
173→          <SkillsPanel
174→            onUseSkill={onUseSkill ?? (() => {})}
175→            onCreateClick={() => setShowCreateDialog(true)}
176→            refreshKey={skillsRefreshKey}
177→          />
178→        ) : (
179→          <MemoriesPanel refreshKey={memoriesRefreshKey} />
180→        )}
181→      </div>
182→      <div className="sidebar__conversations">
183→        <ConversationHistory
184→          activeConversationId={activeConversationId}
185→          onSelect={onConversationSelect}
186→          onNew={onConversationNew}
187→          onDelete={onConversationDelete}
188→          onRename={onConversationRename}
189→          refreshTrigger={conversationRefreshTrigger}
190→          sessionId={sessionId}
191→          streamingConversationIds={streamingConversationIds}
192→        />
193→      </div>
194→      <div className="sidebar__footer">
195→        <a
196→          href="https://github.com/cyyeh/duckdb-data-agent"
197→          target="_blank"
198→          rel="noopener noreferrer"
199→          className="sidebar__github-link"
200→          title={t('viewOnGitHub')}
201→          aria-label={t('viewOnGitHub')}
202→        >
203→          <svg width="16" height="16" viewBox="0 0 24 24" fill="currentColor">
204→            <path d="M12 0c-6.626 0-12 5.373-12 12 0 5.302 3.438 9.8 8.207 11.387.599.111.793-.261.793-.577v-2.234c-3.338.726-4.033-1.416-4.033-1.416-.546-1.387-1.333-1.756-1.333-1.756-1.089-.745.083-.729.083-.729 1.205.084 1.839 1.237 1.839 1.237 1.07 1.834 2.807 1.304 3.492.997.107-.775.418-1.305.762-1.604-2.665-.305-5.467-1.334-5.467-5.931 0-1.311.469-2.381 1.236-3.221-.124-.303-.535-1.524.117-3.176 0 0 1.008-.322 3.301 1.23.957-.266 1.983-.399 3.003-.404 1.02.005 2.047.138 3.006.404 2.291-1.552 3.297-1.23 3.297-1.23.653 1.653.242 2.874.118 3.176.77.84 1.235 1.911 1.235 3.221 0 4.609-2.807 5.624-5.479 5.921.43.372.823 1.102.823 2.222v3.293c0 .319.192.694.801.576 4.765-1.589 8.199-6.086 8.199-11.386 0-6.627-5.373-12-12-12z" />
205→          </svg>
