207→      </div>
208→    </div>
209→    {showCreateDialog && (
210→      <CreateSkillDialog
211→        onClose={() => setShowCreateDialog(false)}
212→        onCreated={() => { setSkillsRefreshKey((k) => k + 1); window.dispatchEvent(new CustomEvent('skills-updated')); }}
213→      />
214→    )}
215→    </>
