  1→import { useState, useEffect, useCallback, useRef } from 'react';
  2→import { useTranslation } from '../hooks/useTranslation';
  3→import './ConversationHistory.css';
  4→
  5→interface Conversation {
  6→  id: string;
  7→  title: string | null;
  8→  created_at: string;
  9→  updated_at: string;
 10→}
 11→
 12→interface ConversationHistoryProps {
 13→  activeConversationId: string | null;
 14→  onSelect: (conversationId: string) => void;
 15→  onNew: () => void;
 16→  onDelete: (conversationId: string) => void;
 17→  onRename: (conversationId: string, title: string) => void;
 18→  refreshTrigger: number;
 19→  sessionId: string;
 20→  streamingConversationIds: Set<string>;
 21→}
 22→
 23→function timeAgo(dateStr: string, t: (key: string, params?: Record<string, string | number>) => string): string {
 24→  const date = new Date(dateStr);
 25→  const now = new Date();
 26→  const seconds = Math.floor((now.getTime() - date.getTime()) / 1000);
 27→  if (seconds < 60) return t('timeJustNow');
 28→  const minutes = Math.floor(seconds / 60);
 29→  if (minutes < 60) return t('timeMinutesAgo', { count: minutes });
 30→  const hours = Math.floor(minutes / 60);
 31→  if (hours < 24) return t('timeHoursAgo', { count: hours });
 32→  const days = Math.floor(hours / 24);
 33→  if (days < 30) return t('timeDaysAgo', { count: days });
 34→  return date.toLocaleDateString();
 35→}
 36→
 37→export function ConversationHistory({
 38→  activeConversationId,
 39→  onSelect,
 40→  onNew,
 41→  onDelete,
 42→  onRename,
 43→  refreshTrigger,
 44→  sessionId,
 45→  streamingConversationIds,
 46→}: ConversationHistoryProps) {
 47→  const { t } = useTranslation();
 48→  const [conversations, setConversations] = useState<Conversation[]>([]);
 49→  const [editingId, setEditingId] = useState<string | null>(null);
 50→  const [editTitle, setEditTitle] = useState('');
 51→  const editInputRef = useRef<HTMLInputElement>(null);
 52→
 53→  // Tick state to force re-render of relative timestamps every 60s
 54→  const [, setTick] = useState(0);
 55→  useEffect(() => {
 56→    const interval = setInterval(() => setTick((t) => t + 1), 60_000);
 57→    return () => clearInterval(interval);
 58→  }, []);
 59→
 60→  const fetchConversations = useCallback(async () => {
 61→    try {
 62→      const res = await fetch('/api/conversations', {
 63→        headers: { 'X-Session-ID': sessionId },
 64→      });
 65→      if (res.ok) {
 66→        setConversations(await res.json());
 67→      }
 68→    } catch {
 69→      // Sidebar fetch failure: show empty list
 70→    }
 71→  }, [sessionId]);
 72→
 73→  useEffect(() => {
 74→    fetchConversations();
 75→  }, [fetchConversations, refreshTrigger]);
 76→
 77→  useEffect(() => {
 78→    if (editingId && editInputRef.current) {
 79→      editInputRef.current.focus();
 80→      editInputRef.current.select();
 81→    }
 82→  }, [editingId]);
 83→
 84→  const handleRenameSubmit = (id: string) => {
 85→    const trimmed = editTitle.trim();
 86→    if (trimmed) {
 87→      onRename(id, trimmed);
 88→    }
 89→    setEditingId(null);
 90→  };
 91→
 92→  const handleDelete = (e: React.MouseEvent, id: string) => {
 93→    e.stopPropagation();
 94→    if (confirm(t('deleteConversationConfirm'))) {
 95→      onDelete(id);
 96→    }
 97→  };
 98→
 99→  const handleStartRename = (e: React.MouseEvent, id: string, currentTitle: string) => {
100→    e.stopPropagation();
101→    setEditingId(id);
102→    setEditTitle(currentTitle || '');
103→  };
104→
105→  return (
106→    <div className="conv-history">
107→      <div className="conv-history__header">
108→        <span className="conv-history__title">{t('conversations')}</span>
109→        <button className="conv-history__new-btn" onClick={onNew} title={t('newConversation')}>
110→          +
111→        </button>
112→      </div>
113→      <div className="conv-history__list">
114→        {conversations.length === 0 ? (
115→          <div className="conv-history__empty">{t('noConversationsYet')}</div>
116→        ) : (
117→          conversations.map((conv) => (
118→            <div
119→              key={conv.id}
120→              className={`conv-history__item ${conv.id === activeConversationId ? 'conv-history__item--active' : ''}`}
121→              onClick={() => onSelect(conv.id)}
122→            >
123→              {editingId === conv.id ? (
124→                <input
125→                  ref={editInputRef}
126→                  className="conv-history__edit-input"
127→                  value={editTitle}
128→                  onChange={(e) => setEditTitle(e.target.value)}
129→                  onBlur={() => handleRenameSubmit(conv.id)}
130→                  onKeyDown={(e) => {
131→                    if (e.key === 'Enter') handleRenameSubmit(conv.id);
132→                    if (e.key === 'Escape') setEditingId(null);
133→                  }}
134→                  onClick={(e) => e.stopPropagation()}
135→                />
136→              ) : (
137→                <>
138→                  <div className="conv-history__item-title">
139→                    {streamingConversationIds.has(conv.id) && (
140→                      <span className="conv-history__streaming-dot" />
141→                    )}
142→                    {conv.title || t('untitled')}
143→                  </div>
144→                  <div className="conv-history__item-meta">
145→                    <span className="conv-history__item-time">{timeAgo(conv.updated_at, t)}</span>
146→                    <span className="conv-history__item-actions">
147→                      <button
148→                        className="conv-history__action-btn"
149→                        onClick={(e) => handleStartRename(e, conv.id, conv.title || '')}
150→                        title={t('rename')}
151→                      >
152→                        <svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2">
153→                          <path d="M11 4H4a2 2 0 0 0-2 2v14a2 2 0 0 0 2 2h14a2 2 0 0 0 2-2v-7" />
154→                          <path d="M18.5 2.5a2.121 2.121 0 0 1 3 3L12 15l-4 1 1-4 9.5-9.5z" />
155→                        </svg>
156→                      </button>
157→                      <button
158→                        className="conv-history__action-btn conv-history__action-btn--danger"
159→                        onClick={(e) => handleDelete(e, conv.id)}
160→                        title={t('deleteConversation')}
161→                      >
162→                        <svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2">
163→                          <polyline points="3 6 5 6 21 6" />
164→                          <path d="M19 6v14a2 2 0 0 1-2 2H7a2 2 0 0 1-2-2V6m3 0V4a2 2 0 0 1 2-2h4a2 2 0 0 1 2 2v2" />
165→                        </svg>
166→                      </button>
167→                    </span>
168→                  </div>
169→                </>
170→              )}
171→            </div>
172→          ))
173→        )}
174→      </div>
175→    </div>
176→  );
177→}
