  padding: 12px 8px;
  text-align: center;
  font-size: 13px;
  color: var(--color-text-disabled);
}

.conv-history__item {
  padding: 6px 8px;
  border-radius: 6px;
  cursor: pointer;
  margin-bottom: 2px;
}

.conv-history__item:hover {
  background: var(--color-bg-hover-strong);
}

.conv-history__item--active {
  background: var(--color-accent-primary-shadow);
}

.conv-history__item-title {
  font-size: 13px;
  color: var(--color-text-primary);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  line-height: 1.4;
}

.conv-history__item--active .conv-history__item-title {
  color: var(--color-accent-primary);
  font-weight: 600;
}

.conv-history__item-meta {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-top: 2px;
}

.conv-history__item-time {
  font-size: 11px;
  color: var(--color-text-disabled);
}

.conv-history__item-actions {
  display: flex;
  gap: 4px;
  opacity: 0;
  transition: opacity 0.15s;
}

.conv-history__item:hover .conv-history__item-actions {
  opacity: 1;
}

.conv-history__action-btn {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 22px;
  height: 22px;
  padding: 0;
  background: none;
  border: none;
  border-radius: 4px;
  color: var(--color-text-muted);
  cursor: pointer;
}

.conv-history__action-btn:hover {
  background: var(--color-bg-hover-strong);
  color: var(--color-text-primary);
}

.conv-history__action-btn--danger:hover {
  color: var(--color-error-text);
}

.conv-history__streaming-dot {
  display: inline-block;
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: var(--color-accent-primary, #6366f1);
  margin-right: 6px;
  vertical-align: middle;
  flex-shrink: 0;
  animation: conv-streaming-pulse 1.5s ease-in-out infinite;
}

@keyframes conv-streaming-pulse {
  0%, 100% { opacity: 1; }
  50% { opacity: 0.3; }
}

.conv-history__edit-input {
